// Growth period: множители к 30-дневной базе (P1.2). Данные под 7/30/90 считаются из одной базы,
// поэтому переключение периода видно во всех колонках прироста.
const PERIODS = ["7", "30", "90"];
const PERIOD_K = { "7": 0.22, "30": 1, "90": 2.68 };
const PERIOD_LABEL = { "7": "Last 7 days", "30": "Last 30 days", "90": "Last 90 days" };
// на проде в поле показывается сам диапазон дат, а не «Last N days»
const PERIOD_RANGE = (function () {
  const out = {}, to = new Date(2026, 7, 3);
  const d2 = function (n) { return ("0" + n).slice(-2); };
  const f = function (d) { return d2(d.getDate()) + "." + d2(d.getMonth() + 1) + "." + d.getFullYear(); };
  PERIODS.forEach(function (pd) {
    const from = new Date(to.getTime() - (parseInt(pd, 10) - 1) * 86400000);
    out[pd] = f(from) + " – " + f(to);
  });
  return out;
})();

// базовый прирост за 30 дней + даты — детерминированно из индекса канала
const CH_META = CH.map(function (c, i) {
  const r = prng(1000 + i);
  const subsG30 = Math.max(200, c[2] * (0.002 + r() * 0.012));
  const viewsG30 = Math.max(1e5, c[3] * (0.004 + r() * 0.016));
  const created = dmy(1 + Math.floor(r() * 27), 1 + Math.floor(r() * 12), 2005 + Math.floor(r() * 14));
  const added = dmy(1 + Math.floor(r() * 27), 1 + Math.floor(r() * 12), 2023 + Math.floor(r() * 3));
  const lastUpd = dmy(24 + Math.floor(r() * 4), 7, 2026);
  return { subsG30: subsG30, viewsG30: viewsG30, created: created, added: added, lastUpd: lastUpd };
});

// строки Basic data под конкретный период (формат — как ждёт bodyRow)
function basicRows(period) {
  const k = PERIOD_K[period] || 1;
  return CH.map(function (c, i) {
    const m = CH_META[i];
    const subsG = m.subsG30 * k, viewsG = m.viewsG30 * k;
    return [
      c[0], c[1], c[5], m.created, m.lastUpd, m.added,
      fmt(c[2]), fmt(c[3]), fmt(c[4]),
      fmtDelta(subsG), fmtDelta(viewsG),
      fmt(c[3] / Math.max(1, c[4])),          // AVV — среднее число просмотров на видео
      fmt(viewsG / Math.max(1, subsG)),       // Views+/Subs+
      c[6], c[7]                              // страна, язык (для фильтров)
    ];
  });
}
// прирост по всем периодам — уходит в window, клиент подменяет ячейки при смене периода
const GROWTH_BY_PERIOD = PERIODS.reduce(function (acc, pd) {
  const k = PERIOD_K[pd];
  acc[pd] = CH.map(function (c, i) {
    const m = CH_META[i], subsG = m.subsG30 * k, viewsG = m.viewsG30 * k;
    return [fmtDelta(subsG), fmtDelta(viewsG), fmt(viewsG / Math.max(1, subsG))];
  });
  return acc;
}, {});

// ================= P1.13: панель фильтров (перенос из прода как есть) =================
// Прод-поведение: правый drawer 417px, ОТКРЫТ по умолчанию, применение мгновенное,
// кнопки Apply нет; сверху «Close panel» и «Clear all»; при непустых фильтрах на кнопке
// Filters — красная точка. Известно, что открытый drawer сжимает таблицу и режет правые
// колонки — это дефект прода, переносим как есть (база для отдельного трека редизайна).
function fSelect(id, label, ph, opts, extra) {
  const o = (opts || []).map(function (v) {
    return '<button class="anf-opt" type="button" role="option" data-anf-opt="' + esc(v) + '">' + esc(v) + '</button>';
  }).join("");
  return '<div class="anf-field" data-anf-field="' + id + '">' +
    '<label class="anf-lbl">' + esc(label) + '</label>' +
    '<div class="anf-select" data-anf-select>' +
      '<button class="anf-trig" type="button" data-anf-trig aria-haspopup="listbox" aria-expanded="false">' +
        '<span class="anf-val is-ph" data-anf-val data-anf-ph="' + esc(ph) + '">' + esc(ph) + '</span>' +
        '<span class="anf-chev" aria-hidden="true">' + IC.chevSelect + '</span>' +
      '</button>' +
      '<div class="anf-menu" data-anf-menu hidden role="listbox">' +
        '<div class="anf-search">' + IC.search + '<input type="text" placeholder="Search" data-anf-search /></div>' +
        '<div class="anf-opts" data-anf-opts>' + o + '</div>' +
      '</div>' +
    '</div>' +
    (extra || "") +
  '</div>';
}
// поиск по названию: то же текстовое поле, но с иконкой лупы
function fSearch(id, label, ph) {
  return '<div class="anf-field" data-anf-field="' + id + '">' +
    '<label class="anf-lbl">' + esc(label) + '</label>' +
    '<div class="an-search anf-search-field">' + IC.search +
      '<input class="an-search__input" type="text" placeholder="' + esc(ph) + '" data-anf-text />' +
    '</div>' +
  '</div>';
}
function fText(id, label, ph) {
  return '<div class="anf-field" data-anf-field="' + id + '">' +
    '<label class="anf-lbl">' + esc(label) + '</label>' +
    '<input class="an-input anf-input" type="text" placeholder="' + esc(ph) + '" data-anf-text />' +
  '</div>';
}
function fRange(id, label, phFrom, phTo) {
  return '<div class="anf-field" data-anf-field="' + id + '">' +
    '<label class="anf-lbl">' + esc(label) + '</label>' +
    '<div class="anf-row">' +
      '<input class="an-input anf-input" type="number" min="0" placeholder="' + esc(phFrom) + '" data-anf-from />' +
      '<span class="anf-dash">—</span>' +
      '<input class="an-input anf-input" type="number" min="0" placeholder="' + esc(phTo) + '" data-anf-to />' +
    '</div>' +
  '</div>';
}
function fSegment(id, label, opts, def) {
  return '<div class="anf-field" data-anf-field="' + id + '">' +
    '<label class="anf-lbl">' + esc(label) + '</label>' +
    '<div class="anf-seg" role="radiogroup">' + opts.map(function (v) {
      // «Enable mode» на проде помечен двумя точками (зелёная/красная) — это про хитмап
      const dots = v === "Enable mode" ? '<span class="anf-dots"><i class="anf-dot anf-dot--g"></i><i class="anf-dot anf-dot--r"></i></span>' : "";
      return '<button class="anf-seg__btn' + (v === def ? " is-on" : "") + '" type="button" role="radio" ' +
             'aria-checked="' + (v === def ? "true" : "false") + '" data-anf-seg="' + esc(v) + '">' + dots + esc(v) + '</button>';
    }).join("") + '</div>' +
  '</div>';
}
// Growth period (P1.2): значение + календарь + чипы 7/30/90. Один компонент, две точки
// монтирования — в Фазе 2 (A4) он переезжает в тулбар без переписывания.
function fGrowthPeriod(withChips) {
  return '<div class="anf-field" data-anf-field="period">' +
    '<label class="anf-lbl">' + (withChips ? "" : '<span class="anf-mark" aria-hidden="true"></span>') + 'Growth period</label>' +
    '<div class="anf-period" data-an-period>' +
      '<button class="anf-trig" type="button" data-an-period-trig>' +
        '<span data-an-period-val>' + PERIOD_RANGE["30"] + '</span>' +
        '<span class="anf-chev" aria-hidden="true">' + IC.calendar + '</span>' +
      '</button>' +
      (withChips ? '<div class="anf-chips" data-an-period-chips>' + PERIODS.map(function (pd) {
        return '<button class="anf-chip' + (pd === "30" ? " is-on" : "") + '" type="button" data-an-period-set="' + pd + '">' + pd + ' days</button>';
      }).join("") + '</div>' : "") +
    '</div>' +
  '</div>';
}
