const AVA = ["--color-avatar-1","--color-avatar-3","--color-avatar-5","--color-avatar-1","--color-avatar-3"];
const ROWS = basicRows("30");   // дефолтный период — 30 дней (P1.2)

function headCell(c){
  let cls = "an-th";
  let style = "width:" + c.w + "px";
  if (c.pin === "check") { cls += " an-th--pin an-th--check"; style += ";left:0"; }
  if (c.pin === "name")  { cls += " an-th--pin an-th--name";  style += ";left:40px"; }
  if (c.stub) cls += " an-th--stub";
  let inner = "";
  if (c.pin === "check") inner = '<button class="an-check" type="button" data-an-check-all aria-label="Select all">' + IC.check + '</button>';
  else if (c.stub) inner = "";
  else if (c.sort) inner = '<span class="an-sort" role="button" tabindex="0" data-an-sort="' + c.id + '">' + c.label + IC.sort + '</span>';
  else inner = c.label;
  return '<div class="' + cls + '" style="' + style + '" data-col="' + c.id + '">' + inner + '</div>';
}

function delta(v){
  if (!v || v === "–") return '<span class="an-muted">–</span>';
  const cls = v[0] === "+" ? "an-delta--pos" : (v[0] === "-" ? "an-delta--neg" : "");
  return '<span class="' + cls + '">' + esc(v) + '</span>';
}
// delta-ячейка с цветным чипом (как на проде: Subs+/Views+): + → зелёный, +0 → оранжевый, − → красный
function deltaCell(v, w){
  if (!v || v === "–") return '<div class="an-td" style="width:' + w + 'px"><span class="an-muted">–</span></div>';
  const t = String(v).replace("+", "").trim();
  const c = v[0] === "-" ? "neg" : (/^0(\D|$)/.test(t) ? "zero" : "pos");
  return '<div class="an-td an-td--metric" style="width:' + w + 'px"><span class="an-heat an-heat--' + c + '"><span class="an-delta--' + c + '">' + esc(v) + '</span></span></div>';
}

function bodyRow(r, i){
  const color = AVA[i % AVA.length];
  const cells = [];
  cells.push('<div class="an-td an-td--pin an-td--check" style="width:40px;left:0"><button class="an-check" type="button" data-an-check aria-label="Select">' + IC.check + '</button></div>');
  cells.push('<div class="an-td an-td--pin an-td--name" style="width:280px;left:40px">' +
      '<a class="an-chan" href="#" tabindex="-1">' +
        '<span class="an-chan__left"><span class="an-chan__ava" style="background:var(' + color + ')">' + esc(r[1]) + '</span>' +
        '<span class="an-chan__name">' + esc(r[0]) + '</span></span>' +
        '<span class="an-chan__fade"></span>' +
      '</a></div>');
  cells.push('<div class="an-td an-td--stub" style="width:20px"></div>');
  // топики: до 2 баджей + «+N» (P1.3). Кликабельными их делает A5 в Фазе 2.
  const tops = Array.isArray(r[2]) ? r[2] : [r[2]];
  const topHtml = '<span class="an-topic" data-an-topic="' + esc(tops[0]) + '">' + esc(tops[0]) + '</span>' +
    (tops.length > 1 ? '<span class="an-topic__more" data-an-topics-more="' + esc(tops.join("|")) + '">+' + (tops.length - 1) + '</span>' : "");
  cells.push('<div class="an-td an-td--topics" style="width:140px"><span class="an-topics">' + topHtml + '</span></div>');
  cells.push('<div class="an-td" style="width:110px">' + esc(r[6]) + '</div>');   // Subs
  cells.push(deltaCell(r[9], 110));                                                  // Subs+
  cells.push('<div class="an-td" style="width:100px">' + esc(r[7]) + '</div>');   // Views
  cells.push(deltaCell(r[10], 120));                                                 // Views+
  cells.push('<div class="an-td" style="width:150px">' + esc(r[12]) + '</div>');  // Views+/Subs+
  cells.push('<div class="an-td" style="width:110px">' + esc(r[8]) + '</div>');   // Vids
  cells.push('<div class="an-td" style="width:80px">' + esc(r[11]) + '</div>');   // AVV
  cells.push('<div class="an-td" style="width:120px">' + esc(r[3]) + '</div>');  // Created
  cells.push('<div class="an-td" style="width:150px">' + esc(r[4]) + '</div>');  // Last upd
  cells.push('<div class="an-td" style="width:150px">' + esc(r[5]) + '</div>');  // Added to base
  return '<div class="an-tr">' + cells.join("") + '</div>';
}

const headHtml = '<div class="an-tr an-tr--head">' + COLS.map(headCell).join("") + '</div>';
const rowsHtml = ROWS.map(bodyRow).join("\n          ");

