// ================= MY COLLECTIONS =================
const COLL_COLS = [
  // свободную ширину забирает Name — она важнее, чем список каналов в Includes
  { id:"name", w:240, label:"Name", sort:true, grow:true },
  { id:"status", w:320, label:"Status", sort:true },
  { id:"quantity", w:120, label:"Quantity", sort:true },
  { id:"created", w:140, label:"Created on", sort:true },
  { id:"owner", w:160, label:"Owner" },
  { id:"shared", w:150, label:"Shared with" },
  { id:"actions", w:120, label:"" },
];

function collHeadCell(c){
  let cls = "an-th" + (c.grow ? " an-th--grow" : "");
  let inner = c.sort ? '<span class="an-sort" role="button" tabindex="0" data-an-sort="' + c.id + '">' + c.label + IC.sort + '</span>' : c.label;
  return '<div class="' + cls + '" style="width:' + c.w + 'px" data-col="' + c.id + '">' + inner + '</div>';
}
function ava(a, cls){ return '<span class="' + (cls || "mc-ava") + '" style="background:var(' + a.c + ')"' +
  (a.n ? ' title="' + esc(a.n) + '"' : '') + '>' + esc(a.i) + '</span>'; }
function collRow(r){
  const cells = [];
  cells.push('<div class="an-td an-td--grow" style="width:240px"><span class="mc-name">' + esc(r.name) + '</span></div>');
  // статус — ОДНА пилюля: иконка + подпись + разделитель + ссылка внутри (как на проде)
  let st = '';
  if (r.status === "activated") {
    st = '<span class="mc-status mc-status--green">' + IC.thumbUp + '<span class="mc-status__t">Activated</span>' +
         '<span class="mc-status__sep"></span><a class="mc-status__link" href="analytics-deep-data.html">View deep data</a></span>';
  } else if (r.status === "pending") {
    st = '<span class="mc-status mc-status--orange">' + IC.progress + '<span class="mc-status__t">Collecting data</span></span>';
  } else if (r.status === "created") {
    st = '<span class="mc-status mc-status--gray">' + IC.check + '<span class="mc-status__t">Created</span>' +
         '<span class="mc-status__sep"></span><button class="mc-status__link" type="button" data-mc-activate>Activate deep data</button></span>';
  } else if (r.status === "inactive") {
    st = '<span class="mc-status mc-status--gray">' + IC.archive + '<span class="mc-status__t">Deactivated</span>' +
         '<span class="mc-status__sep"></span><button class="mc-status__link" type="button" data-mc-activate>Activate deep data</button></span>';
  }
  cells.push('<div class="an-td" style="width:320px"><div class="mc-statuscell">' + st + '</div></div>');
  cells.push('<div class="an-td" style="width:120px">' + r.qty + '</div>');
  cells.push('<div class="an-td" style="width:140px">' + esc(r.created) + '</div>');
  cells.push('<div class="an-td" style="width:160px"><span class="mc-owner">' + ava(r.owner) + '<span class="mc-owner__name">' + esc(r.owner.name) + '</span></span></div>');
  // пустая колонка Shared with на проде показывает «Not shared» с иконкой
  const sharedCell = r.shared.length
    ? '<span class="mc-shared">' + r.shared.map(function (a) { return ava(a); }).join("") + '</span>'
    : '<span class="mc-noshare">' + IC.shareOff + 'Not shared</span>';
  cells.push('<div class="an-td" style="width:150px">' + sharedCell + '</div>');
  // действия строки: шеринг вынесен отдельной иконкой, остальное — под «⋮»
  cells.push('<div class="an-td mc-acts" style="width:120px">' +
    '<button class="mc-more" type="button" aria-label="Share collection" title="Share" data-mc-share-btn>' + IC.share + '</button>' +
    '<button class="mc-more" type="button" aria-label="Actions" data-mc-more data-status="' + r.status + '" data-name="' + esc(r.name) + '">' + IC.dots + '</button>' +
  '</div>');
  return '<div class="an-tr" data-mc-row data-name="' + esc(r.name) + '"' +
    ' data-channels="' + esc(r.includes.join("|")) + '"' +
    (r.sample ? ' data-sample="1"' : '') + ' data-owner="' + esc(r.owner.name) + '"' +
    ' data-shared="' + esc(r.shared.map(function (a) { return a.n || a.i; }).join("|")) + '">' + cells.join("") + '</div>';
}
const collHead = '<div class="an-tr an-tr--head">' + COLL_COLS.map(collHeadCell).join("") + '</div>';
const collBody = COLL_ROWS.map(collRow).join("\n          ");

