function buildPage(src, title, inner, current){
  let h = src;
  h = h.replace("<title>Home — SubSub</title>", "<title>" + title + " — SubSub</title>");
  h = h.replace('class="sidebar-item sidebar-item--home is-active"', 'class="sidebar-item sidebar-item--home"');
  h = h.replace('id="space-analytics" value="analytics" />', 'id="space-analytics" value="analytics" checked />');
  h = h.replace("<body>", '<body class="is-open" data-space="analytics" data-ce-statuses="' +
    JSON.stringify(COLL_STATUSES).replace(/"/g, "&quot;") + '">');
  h = h.replace('<p class="submenu__title" id="submenuTitle"></p>', '<p class="submenu__title" id="submenuTitle">Analytics</p>');
  h = h.replace('<div class="submenu__menu" data-space="analytics" hidden>', '<div class="submenu__menu" data-space="analytics">');
  // подсветка активного подпункта (ссылки уже проставлены генератором меню)
  const markCurrent = (url, isCur) => {
    if (!isCur) return;
    h = h.replace('<a class="m-item" href="' + url + '"', '<a class="m-item is-current" href="' + url + '"');
  };
  // основной вариант навигации: под Deep data стоит отдельный пункт Videos data.
  // Исключение — альтернативная страница со свичем (current === "deepTabs").
  if (current !== "deepTabs") {
    h = h.replace('<a class="m-item" href="analytics-deep-data.html"><span class="m-ico"></span>Deep data</a>',
      '<a class="m-item" href="analytics-deep-data.html"><span class="m-ico"></span>Deep data</a>' +
      '<a class="m-item" href="analytics-videos-data.html"><span class="m-ico"></span>Videos data</a>');
  }
  markCurrent("analytics-basic-data.html", current === "basic");
  markCurrent("analytics-deep-data.html", current === "deep" || current === "deepTabs");
  markCurrent("analytics-collections.html", current === "collections");
  markCurrent("analytics-videos-data.html", current === "videos");
  markCurrent("analytics-reports.html", current === "reports");
  // базовые коллекции (те же, что в списке My collections) — единый источник для дропдауна
  // назначения в модалке sourcing; страницы Basic data / My collections читают их из window
  const seed = JSON.stringify(COLL_ROWS.map(function (r) {
    return { name: r.name, status: r.status, qty: r.qty, sample: !!r.sample, owner: r.owner.name, channels: r.channels.slice() };
  }));
  // каналы: подсказки для референсов + источник для фильтров и поиска по базе (P1.13, D2)
  const chSeed = JSON.stringify(ROWS.map(function (r, i) {
    return {
      name: r[0], initial: r[1], color: AVA[i % AVA.length],
      topics: r[2], country: r[13], language: r[14],
      subs: r[6], views: r[7], added: r[5]
    };
  }));
  // справочники + прирост по периодам (P1.2): клиент подменяет ячейки при смене периода
  const dictSeed = JSON.stringify({
    topics: TOPIC_LIST, countries: COUNTRY_LIST, languages: LANG_LIST,
    periods: PERIODS, periodLabels: PERIOD_LABEL, periodRanges: PERIOD_RANGE, defaultPeriod: "30",
    // «сегодня» прототипа фиксировано, чтобы календарь и диапазоны не плыли между сборками
    today: "2026-08-03",
    months: ["January","February","March","April","May","June","July","August","September","October","November","December"],
    weekdays: ["Mo","Tu","We","Th","Fr","Sa","Su"],
    // база прироста за 30 дней числами — кастомный период масштабируется от неё
    growthBase: CH_META.map(function (m) { return [Math.round(m.subsG30), Math.round(m.viewsG30)]; }),
    // Reports: варианты типов, свои каналы и дата добавления первого канала коллекции
    // участники организации — подсказки в шеринге коллекции
    orgMembers: CE_MEMBERS,
    reportTypes: REP_TYPES,
    ownChannels: REP_OWN_CHANNELS,
    firstChannelAdded: "19.05.2023"
  });
  const growthSeed = JSON.stringify(GROWTH_BY_PERIOD);
  h = h.replace('<script src="js/nav.js"></script>',
    '<script src="js/nav.js"></script>\n  <script>window.SUBSUB_BASE_COLLECTIONS = ' + seed + ';' +
    'window.SUBSUB_CHANNELS = ' + chSeed + ';' +
    'window.SUBSUB_DICT = ' + dictSeed + ';' +
    'window.SUBSUB_GROWTH = ' + growthSeed + ';</script>' +
    '\n  <script src="js/analytics.js"></script>');
  const ms = h.indexOf('<main class="main">');
  const me = h.indexOf("</main>", ms);
  return h.slice(0, ms + '<main class="main">'.length) + inner + "\n  " + h.slice(me);
}


// ================= варианты навигации по видео =================
// ОСНОВНОЙ вариант: Deep data без свича, видео — отдельная страница Videos data
